create table profiles (id uuid primary key, email text, full_name text, created_at timestamptz default now());
create table products (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), name text not null, url text, category text, price text, target_customer text, main_problem text, main_benefit text, key_features text, competitor_link text, tone text, created_at timestamptz default now());
create table ad_packs (id uuid primary key default gen_random_uuid(), product_id uuid references products(id), user_id uuid references profiles(id), title text not null, product_summary text, created_at timestamptz default now());
create table generated_sections (id uuid primary key default gen_random_uuid(), ad_pack_id uuid references ad_packs(id) on delete cascade, section_key text not null, content jsonb not null, saved boolean default false, created_at timestamptz default now());
create table swipe_file_items (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), ad_link text not null, platform text, product text, hook text, angle text, notes text, status text check (status in ('Idea','Testing','Winner','Loser')) default 'Idea', created_at timestamptz default now());
create table usage_events (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), event_type text not null, metadata jsonb default '{}', created_at timestamptz default now());
create table subscriptions (id uuid primary key default gen_random_uuid(), user_id uuid references profiles(id), plan text not null default 'Starter', stripe_customer_id text, stripe_subscription_id text, status text default 'demo', current_period_end timestamptz, created_at timestamptz default now());
